rows.text:
{!accountUnavailable && portfolio.positions.length > 0 && (
                    <p className="mt-2 text-xs text-muted-foreground" role="status" aria-live="polite">
                      {quoteLookupFailed ? "Provider status could not be checked; valuations may rely on older data." :
                        Object.keys(quoteCoverage).length === 0 ? "Checking quote sources for your holdings…" :
                        `${Object.values(quoteCoverage).filter(q => q.status === "simulator").length} simulator-only · ${Object.values(quoteCoverage).filter(q => q.status === "stale").length} stale · ${Object.values(quoteCoverage).filter(q => q.status === "previous_close").length} previous-close holdings. See each asset below.`}
                    </p>
                  )}

{quoteLookupFailed ? "Provider status could not be checked; valuations may rely on older data." :
                        Object.keys(quoteCoverage).length === 0 ? "Checking quote sources for your holdings…" :
                        `${Object.values(quoteCoverage).filter(q => q.status === "simulator").length} simulator-only · ${Object.values(quoteCoverage).filter(q => q.status === "stale").length} stale · ${Object.values(quoteCoverage).filter(q => q.status === "previous_close").length} previous-close holdings. See each asset below.`}

{user && <div className="text-xs text-muted-foreground mt-3 max-w-2xl leading-relaxed">
                    <p>{PRICE_REFRESH_COPY} Account values are checked while TradeHQ is open and whenever supported server updates arrive.</p>
                    {accountPricing && <p className="mt-1">{priceLabel(accountPricing.status, accountPricing.observed)}. {quoteTimeLabel(accountPricing.fetched, accountPricing.observed)}</p>}
                    {account?.receivedAt && <p>Account snapshot received {new Date(account.receivedAt).toLocaleString()}.</p>}
                    {account?.error && <p role="status">Account refresh failed. {account.error} {account.portfolio
                      ? "Showing the last confirmed account snapshot. TradeHQ will retry automatically."
                      : "Account values are unavailable until a refresh succeeds."}</p>}
                  </div>}

{account?.error && <p role="status">Account refresh failed. {account.error} {account.portfolio
                      ? "Showing the last confirmed account snapshot. TradeHQ will retry automatically."
                      : "Account values are unavailable until a refresh succeeds."}</p>}

{account.portfolio
                      ? "Showing the last confirmed account snapshot. TradeHQ will retry automatically."
                      : "Account values are unavailable until a refresh succeeds."}

{snapshotChange ? (
                  <p
                    className={cn(
                      "text-2xs mt-0.5 tabular-nums",
                      snapshotChange.dollars >= 0 ? "text-success" : "text-destructive",
                    )}
                  >
                    {snapshotChange.dollars >= 0 ? "+" : ""}${snapshotChange.dollars.toFixed(2)}
                    {snapshotChange.percent !== null && ` (${snapshotChange.percent >= 0 ? "+" : ""}${snapshotChange.percent.toFixed(2)}%)`}
                    {" "}since <time dateTime={snapshotChange.baselineAt.toISOString()}>{snapshotChange.baselineAt.toLocaleString()}</time>
                  </p>
                ) : (
                  <p className="text-2xs text-muted-foreground mt-0.5">Cash + Positions</p>
                )}

{totalProfitLoss >= 0 ? (
                      <TrendingUp className="w-4 h-4 text-success" />
                    ) : (
                      <TrendingDown className="w-4 h-4 text-destructive" />
                    )}

{account
          ? "Account snapshots are recorded on this device when TradeHQ receives them. With multiple observations, the reference line provides a comparison."
          : "Earlier local practice snapshots may include simulated backfill. The reference line is for comparison."}

{hasHistory && <span className={cn(
            "font-semibold flex items-center gap-1",
            isPositive ? "text-success" : "text-destructive"
          )}>
            {isPositive ? <TrendingUp className="w-4 h-4" /> : <TrendingDown className="w-4 h-4" />}
            {isPositive ? '+' : ''}${change.toFixed(2)}{changePercent !== null && ` (${isPositive ? '+' : ''}${changePercent}%)`} since first saved snapshot
          </span>}

{showStopLoss && stopLossBreached && (
          <div className="mt-2 px-3 py-2 bg-destructive/20 border border-destructive/50 rounded-lg">
            <p className="text-sm font-medium text-destructive flex items-center gap-2">
              <Shield className="w-4 h-4" />
              Reference threshold crossed. Portfolio dropped below ${stopLossValue.toFixed(2)}
            </p>
          </div>
        )}

{!hasHistory && <p className="text-sm text-muted-foreground mb-4" role="status">
        {hasCurrentObservation
          ? "One real portfolio observation is available. The point below shows the current snapshot, not a historical trend. Later observations on this device will build the chart."
          : "History is unavailable on this device until at least two snapshots are recorded. Your account portfolio value and recorded trades are separate from this optional local chart."}
      </p>}

{hasCurrentObservation
          ? "One real portfolio observation is available. The point below shows the current snapshot, not a historical trend. Later observations on this device will build the chart."
          : "History is unavailable on this device until at least two snapshots are recorded. Your account portfolio value and recorded trades are separate from this optional local chart."}

{data.length > 0 && <div className="min-w-0" data-portfolio-chart-state={hasHistory ? "trend" : "single-observation"}>
        <ResponsiveContainer width="100%" height={hasHistory ? 300 : 210}>
        <LineChart
          data={data}
          margin={{ top: 12, right: 18, bottom: 10, left: 10 }}
          accessibilityLayer
          title="Practice portfolio history chart"
          desc={hasHistory
            ? "Use the left and right arrow keys to review saved snapshot times and values."
            : "One saved practice portfolio observation."}
        >
          <XAxis 
            dataKey="time" 
            stroke="hsl(var(--muted-foreground))"
            tick={{ fill: 'hsl(var(--muted-foreground))', fontSize: 11 }}
            minTickGap={16}
          />
          <YAxis
            width={108}
            tickMargin={10}
            stroke="hsl(var(--muted-foreground))"
            tick={{ fill: 'hsl(var(--muted-foreground))', fontSize: 11 }}
            domain={chartDomain}
            tickFormatter={(value: number) => formatPortfolioChartTick(value, chartDomain[1] - chartDomain[0])}
          />
          <Tooltip
            position={{ x: 0, y: 0 }}
            wrapperStyle={{ maxWidth: '100%', whiteSpace: 'normal' }}
            contentStyle={{ 
              backgroundColor: 'hsl(var(--card))',
              border: '1px solid hsl(var(--border))',
              borderRadius: '8px',
            }}
            labelStyle={{ color: 'hsl(var(--foreground))' }}
          />

          {/* Stop Loss Line */}
          {hasHistory && showStopLoss && referenceInView && (
            <ReferenceLine
              y={stopLossValue}
              stroke="hsl(var(--destructive))"
              strokeDasharray="5 5"
              strokeWidth={2}
            />
          )}

          {/* Initial Value Line */}
          {hasHistory && <ReferenceLine
            y={initialValue}
            stroke="hsl(var(--muted-foreground))"
            strokeDasharray="3 3"
            strokeWidth={1}
          />}

          <Line 
            type="monotone" 
            dataKey="value" 
            name="Portfolio value"
            stroke={stopLossBreached ? "hsl(var(--destructive))" : "hsl(var(--primary))"} 
            strokeWidth={3}
            dot={{ fill: stopLossBreached ? 'hsl(var(--destructive))' : 'hsl(var(--primary))', r: 4 }}
            activeDot={{ r: 6 }}
          />
        </LineChart>
        </ResponsiveContainer>
        {hasHistory && <div className="mt-4 space-y-2 border-t border-border/50 pt-3 text-xs text-muted-foreground">
          <p>First saved observation: <strong className="font-medium text-foreground">{initialValue.toLocaleString("en-US", { style: "currency", currency: "USD" })}</strong></p>
          <p role="status" aria-live="polite" data-portfolio-reference-status>
            {showStopLoss
              ? <>10% downside reference: <strong className="font-medium text-foreground">{stopLossValue.toLocaleString("en-US", { style: "currency", currency: "USD" })}</strong>. {referenceInView
                  ? "The dashed reference line is visible on the chart."
                  : "The reference is below this chart's visible scale; it is shown here without flattening your actual portfolio changes."}</>
              : "10% downside reference hidden."}
          </p>
          <p>This is an educational comparison, not a stop-loss order.</p>
        </div>}
      </div>}

{hasHistory && showStopLoss && referenceInView && (
            <ReferenceLine
              y={stopLossValue}
              stroke="hsl(var(--destructive))"
              strokeDasharray="5 5"
              strokeWidth={2}
            />
          )}

{referenceInView
                  ? "The dashed reference line is visible on the chart."
                  : "The reference is below this chart's visible scale; it is shown here without flattening your actual portfolio changes."}

{analytics.allocationData.length > 0 ? (
          <div className="flex items-center gap-6">
            <ResponsiveContainer width={180} height={180}>
              <PieChart>
                <Pie
                  data={analytics.allocationData}
                  cx="50%"
                  cy="50%"
                  innerRadius={50}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {analytics.allocationData.map((_, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip 
                  formatter={(value: number) => `$${value.toFixed(2)}`}
                  contentStyle={{ backgroundColor: 'hsl(0 0% 8%)', border: '1px solid hsl(0 0% 20%)' }}
                />
              </PieChart>
            </ResponsiveContainer>
            <div className="flex-1 space-y-3">
              {analytics.allocationData.map((item, index) => (
                <div key={item.name}>
                  <div className="flex justify-between text-sm mb-1">
                    <span className="flex items-center gap-2">
                      <div className="w-3 h-3 rounded-full" style={{ backgroundColor: COLORS[index % COLORS.length] }} />
                      {item.name}
                    </span>
                    <span className="font-medium">{item.percentage.toFixed(1)}%</span>
                  </div>
                  <Progress value={item.percentage} aria-label={`${item.name} allocation`} className="h-2" />
                </div>
              ))}
            </div>
          </div>
        ) : (
          <p className="text-muted-foreground text-center py-8">No positions yet</p>
        )}

{Object.keys(portfolio.positions.reduce((acc, pos) => {
              acc[pos.asset.type] = true;
              return acc;
            }, {} as Record<string, boolean>)).length}

{summary.emotions.length === 0 ? (
                  <p className="text-muted-foreground">No emotion tags recorded.</p>
                ) : (
                  <ul className="space-y-2">
                    {summary.emotions.map(({ emotion, count }) => (
                      <li key={emotion} className="flex flex-wrap items-center justify-between gap-2">
                        <Badge variant="outline">{emotion}</Badge>
                        <span>{count} of {summary.totalEntries} {summary.totalEntries === 1 ? "entry" : "entries"}</span>
                      </li>
                    ))}
                  </ul>
                )}

{summary.emotions.map(({ emotion, count }) => (
                      <li key={emotion} className="flex flex-wrap items-center justify-between gap-2">
                        <Badge variant="outline">{emotion}</Badge>
                        <span>{count} of {summary.totalEntries} {summary.totalEntries === 1 ? "entry" : "entries"}</span>
                      </li>
                    ))}

{trade.journal && (
                        <span className="text-xs text-muted-foreground flex items-center gap-1 mt-1">
                          📝 Has notes
                        </span>
                      )}

{sortedTrades.length > 0 && (
        <div className="text-center text-sm text-muted-foreground">
          Showing {sortedTrades.length} of {trades.length} trades
        </div>
      )}

{insights.map((insight, index) => (
          <div
            key={`${insight.type}-${index}`}
            className="flex gap-3 rounded-xl border border-white/8 bg-white/[0.02] p-3"
          >
            <div className={cn("mt-0.5 shrink-0", TYPE_STYLES[insight.type])}>
              {insight.icon}
            </div>
            <p className="text-sm leading-6 text-foreground/90">{insight.text}</p>
          </div>
        ))}

{authLoading ? "Verifying whether this is a guest or account portfolio." : signedIn
              ? "Signed-in portfolios come from server-recorded trades. Sign out to restore a separate guest backup; imports cannot replace account history."
              : "Choose a previously downloaded TradeHQ .json file. Inspect its values before replacing this browser's guest portfolio."}

{unreadable && <div role="alert" className="mt-4 text-sm rounded-xl border border-amber-500/30 p-3">
        An earlier local portfolio couldn't be interpreted, so its original bytes were preserved. <button type="button" className="text-primary underline" onClick={downloadOriginal}>Download the original for manual recovery.</button>
      </div>}

{EXAMPLES.map((ex) => (
          <button
            key={ex}
            onClick={() => {
              setPrompt(ex);
              runQuery(ex);
            }}
            disabled={loading}
            className="text-2xs px-2.5 py-1 rounded-full bg-white/[0.04] border border-white/[0.08] text-muted-foreground hover:text-foreground hover:bg-white/[0.08] transition-colors disabled:opacity-50"
          >
            {ex}
          </button>
        ))}

{!hasPositions && (
        <div className="mt-4 p-4 rounded-lg bg-warning/5 border border-warning/20 text-2xs text-warning">
          Buy some assets in the Trade tab first — the scenario engine needs positions to simulate.
        </div>
      )}

{narrative && (
            <div className="p-4 rounded-lg bg-primary/5 border border-primary/20">
              <p className="text-xs text-muted-foreground italic leading-relaxed">{narrative}</p>
            </div>
          )}
